node -e "
const {google} = require('googleapis');
const fs = require('fs');

const tokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json'));
const account = tokens.accounts.default;

const oauth2Client = new google.auth.OAuth2(
    account.client_id,
    account.client_secret,
    'http://localhost'
);

oauth2Client.setCredentials({
    refresh_token: account.refresh_token,
    access_token: account.access_token,
    expiry_date: account.expiry_date,
    scope: account.scope,
});

const calendar = google.calendar({version: 'v3', auth: oauth2Client});

calendar.events.list({
    calendarId: 'primary',
    timeMin: '2026-01-06T00:00:00Z',
    timeMax: '2026-01-10T23:59:59Z',
    singleEvents: true,
    orderBy: 'startTime',
}).then(res => {
    console.log('SUCCESS! Events:', JSON.stringify(res.data.items, null, 2));
}).catch(err => {
    console.error('ERROR:', err.message);
    if (err.response) {
        console.error('Response:', JSON.stringify(err.response.data, null, 2));
    }
});
" 2>&1

