node -e "
const {google} = require('googleapis');
const fs = require('fs');

// Read credentials and tokens
const credentials = JSON.parse(fs.readFileSync('/root/auth/gmail/credentials.json'));
const tokens = JSON.parse(fs.readFileSync('/root/auth/gmail/tokens.json'));
const account = tokens.accounts.default;

const {client_id, client_secret} = credentials.installed;

const oauth2Client = new google.auth.OAuth2(client_id, client_secret, 'http://localhost');

// Set just the refresh token, let it fetch a new access token
oauth2Client.setCredentials({
    refresh_token: account.refresh_token,
});

// Try to force refresh with specific scopes
oauth2Client.refreshAccessToken().then(({credentials}) => {
    console.log('New token scopes:', credentials.scope);
    console.log('Token type:', credentials.token_type);
    console.log('Token (first 50):', credentials.access_token.substring(0, 50));
}).catch(err => {
    console.error('Refresh error:', err.message);
});
" 2>&1

