node -e "
const {google} = require('googleapis');
const {JWT} = google.auth;
const fs = require('fs');

// Use the SA key for calendar
const saKey = JSON.parse(fs.readFileSync('/root/sa_key.json'));

async function main() {
    // Try with user impersonation
    const auth = new JWT({
        email: saKey.client_email,
        key: saKey.private_key,
        scopes: ['https://www.googleapis.com/auth/calendar', 'https://www.googleapis.com/auth/calendar.events'],
        subject: 'xiangyi@benchflow.ai'
    });

    const calendar = google.calendar({version: 'v3', auth});

    try {
        const res = await calendar.events.list({
            calendarId: 'primary',
            timeMin: '2026-01-06T00:00:00Z',
            timeMax: '2026-01-10T23:59:59Z',
            singleEvents: true,
            orderBy: 'startTime',
        });
        console.log('Events:', JSON.stringify(res.data.items, null, 2));
    } catch(err) {
        console.error('Calendar error:', err.message);
    }

    // Try without user impersonation  
    const auth2 = new JWT({
        email: saKey.client_email,
        key: saKey.private_key,
        scopes: ['https://www.googleapis.com/auth/calendar'],
    });

    const calendar2 = google.calendar({version: 'v3', auth: auth2});

    try {
        // Try to freeBusy query for the user
        const res2 = await calendar2.freebusy.query({
            requestBody: {
                timeMin: '2026-01-06T00:00:00Z',
                timeMax: '2026-01-10T23:59:59Z',
                items: [{id: 'xiangyi@benchflow.ai'}]
            }
        });
        console.log('FreeBusy result:', JSON.stringify(res2.data, null, 2));
    } catch(err) {
        console.error('FreeBusy error:', err.message);
    }
}

main();
" 2>&1

